<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Http\Kernel::class); $request = Illuminate\Http\Request::create("/api/updater/run", "POST", ["step" => "migrate"]); try { $app->make(Illuminate\Contracts\Http\Kernel::class)->bootstrap(); DB::purge(); Artisan::call("config:clear"); $ran = DB::table("migrations")->pluck("migration")->toArray(); $files = File::glob(database_path("migrations/*.php")); $pendingCount = 0; foreach ($files as $f) { if (!in_array(pathinfo($f, PATHINFO_FILENAME), $ran)) $pendingCount++; } echo "Pending count: $pendingCount\n"; Artisan::call("migrate", ["--force" => true]); echo Artisan::output(); } catch (\Throwable $e) { echo "Exception:\n" . $e->getMessage() . "\n" . $e->getFile() . ":" . $e->getLine() . "\n" . $e->getTraceAsString(); }
